struct Order {
    var items: [Int]
    var discount: Int

    var summary: String {
        let total = discountedTotal()
        let label = total > 100 ? "large" : "small"
        return "\(label): \(total)"
    }

    private func discountedTotal() -> Int {
        let subtotal = items.reduce(0, +)
        return max(0, subtotal - discount)
    }
}

